<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { generateForumImage } from '../../../services/forumMediaGeneration'
import type { ForumCircle, ForumPostType } from '../../../types/forum'

const props = defineProps<{ visible: boolean }>()
const emit = defineEmits<{ (e: 'close'): void; (e: 'create', value: Pick<ForumCircle, 'name'|'avatar'|'description'|'contentScope'|'tags'|'joinMode'|'anonymousMode'|'contentPermissions'|'mediaPermissions'|'searchable'|'isPublic'>): void }>()
const name=ref('');const avatar=ref('');const description=ref('');const contentScope=ref('');const tags=ref('');const joinMode=ref<ForumCircle['joinMode']>('public');const anonymousMode=ref<ForumCircle['anonymousMode']>('per-post');const avatarBusy=ref(false);const avatarError=ref('');const fileInput=ref<HTMLInputElement|null>(null)
const permissions=ref<ForumPostType[]>(['text','single-image','multi-image','long-article','poll','qa','link','anonymous'])
const valid=computed(()=>name.value.trim().length>=2&&description.value.trim()&&contentScope.value.trim())
watch(()=>props.visible,visible=>{if(!visible)return;name.value='';avatar.value='';description.value='';contentScope.value='';tags.value='';joinMode.value='public';anonymousMode.value='per-post';avatarError.value=''})
const togglePermission=(value:ForumPostType)=>{const index=permissions.value.indexOf(value);if(index>=0)permissions.value.splice(index,1);else permissions.value.push(value)}
const upload=(event:Event)=>{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{avatar.value=String(reader.result||'')};reader.readAsDataURL(file);(event.target as HTMLInputElement).value=''}
const generateAvatar=async()=>{if(!name.value.trim()||avatarBusy.value)return;avatarBusy.value=true;avatarError.value='';try{avatar.value=(await generateForumImage(`为“${name.value.trim()}”论坛圈子生成简洁、无文字、适合小尺寸裁切的头像，主题：${contentScope.value.trim()||description.value.trim()}`)).url}catch(cause){avatarError.value=cause instanceof Error?cause.message:String(cause)}finally{avatarBusy.value=false}}
const submit=()=>{if(!valid.value)return;emit('create',{name:name.value.trim(),avatar:avatar.value||name.value.trim().slice(0,1),description:description.value.trim(),contentScope:contentScope.value.trim(),tags:tags.value.split(/[，,\s]+/).map(item=>item.trim()).filter(Boolean).slice(0,6),joinMode:joinMode.value,anonymousMode:anonymousMode.value,contentPermissions:[...permissions.value],mediaPermissions:permissions.value.some(item=>['single-image','multi-image'].includes(item))?['image']:[],searchable:joinMode.value!=='hidden',isPublic:!['invite','hidden'].includes(joinMode.value)})}
</script>
<template>
  <div v-if="visible" class="overlay" @click.self="!avatarBusy&&emit('close')"><section role="dialog" aria-modal="true" aria-labelledby="circle-create-title"><header><button type="button" @click="emit('close')">取消</button><b id="circle-create-title">创建圈子</b><button type="button" :disabled="!valid||avatarBusy" @click="submit">创建</button></header><div class="scroll">
    <div class="avatar-editor"><button class="avatar" type="button" @click="fileInput?.click()"><img v-if="avatar&&avatar.includes(':')" :src="avatar"><span v-else>{{avatar||name.trim().slice(0,1)||'圈'}}</span></button><div><b>圈子头像</b><p>上传相册图片、AI 生成或使用文字头像</p><div><button type="button" @click="fileInput?.click()">选择图片</button><button type="button" :disabled="avatarBusy||!name.trim()" @click="generateAvatar">{{avatarBusy?'生成中…':'AI 生成'}}</button><button type="button" @click="avatar=name.trim().slice(0,1)">文字头像</button></div></div><input ref="fileInput" type="file" accept="image/*" @change="upload"></div><p v-if="avatarError" class="error">{{avatarError}}</p>
    <label><span>圈子名称</span><input v-model="name" maxlength="24" placeholder="简短、好记的名称"></label><label><span>圈子简介</span><textarea v-model="description" maxlength="180" placeholder="展示给访客看的简短介绍"></textarea></label><label><span>这里主要聊什么</span><textarea v-model="contentScope" maxlength="500" placeholder="具体描述讨论范围，后续生成内容会遵守这里"></textarea></label><label><span>标签</span><input v-model="tags" maxlength="60" placeholder="校园、美食、日常（逗号分隔）"></label>
    <div class="option-block"><span>加入方式</span><div class="choices"><button v-for="item in [{v:'public',t:'公开加入'},{v:'application',t:'申请加入'},{v:'invite',t:'私密邀请'}]" :key="item.v" type="button" :class="{active:joinMode===item.v}" @click="joinMode=item.v as ForumCircle['joinMode']">{{item.t}}</button></div></div><div class="option-block"><span>匿名方式</span><div class="choices"><button v-for="item in [{v:'disabled',t:'不允许'},{v:'per-post',t:'每帖匿名'},{v:'circle-fixed',t:'圈内固定'}]" :key="item.v" type="button" :class="{active:anonymousMode===item.v}" @click="anonymousMode=item.v as ForumCircle['anonymousMode']">{{item.t}}</button></div></div>
    <div class="option-block"><span>允许发布</span><div class="permission-list"><button v-for="item in [{v:'text',t:'文字'},{v:'single-image',t:'图片'},{v:'long-article',t:'长文'},{v:'poll',t:'投票'},{v:'qa',t:'问答'},{v:'link',t:'链接'},{v:'voice',t:'语音'},{v:'short-video',t:'短视频'},{v:'anonymous',t:'匿名'},{v:'lottery',t:'抽奖'}]" :key="item.v" type="button" :class="{active:permissions.includes(item.v as ForumPostType)}" @click="togglePermission(item.v as ForumPostType)"><i>✓</i>{{item.t}}</button></div></div>
  </div></section></div>
</template>
<style scoped>
.overlay{position:absolute;inset:0;z-index:530;display:flex;align-items:flex-end;background:rgba(0,0,0,.34)}.overlay>section{box-sizing:border-box;width:100%;max-height:min(94%,760px);display:flex;flex-direction:column;border-radius:16px 16px 0 0;background:var(--sys-bg-secondary,#fff);padding-bottom:env(safe-area-inset-bottom,0)}header{display:grid;grid-template-columns:58px 1fr 58px;align-items:center;min-height:50px;padding:0 12px;border-bottom:1px solid var(--border-color,rgba(0,0,0,.06));text-align:center}header b{min-width:0;overflow:hidden;font-size:14px;white-space:nowrap;text-overflow:ellipsis}header button{height:30px;border:0;background:transparent;color:var(--accent-color,#2b7de9);font:inherit;font-size:12.5px}header button:first-child{text-align:left;color:var(--text-secondary,#666)}header button:last-child{text-align:right;font-weight:600}button:disabled{opacity:.35}.scroll{min-height:0;overflow:auto;padding:13px 15px}.avatar-editor{display:flex;min-width:0;align-items:center;gap:11px;padding-bottom:12px}.avatar-editor>.avatar{display:flex;flex:0 0 52px;width:52px;height:52px;align-items:center;justify-content:center;overflow:hidden;border:0;border-radius:14px;background:var(--sys-bg-tertiary,#eceef1);color:var(--text-primary,#333);font-size:18px;font-weight:650}.avatar img{width:100%;height:100%;object-fit:cover}.avatar-editor>div{min-width:0;flex:1}.avatar-editor b{font-size:12.5px}.avatar-editor p{margin:2px 0 6px;color:var(--text-tertiary,#999);font-size:9.8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.avatar-editor>div>div{display:flex;gap:5px;overflow:auto}.avatar-editor>div button{flex:0 0 auto;height:25px;border:0;border-radius:7px;background:var(--sys-bg-primary,#f1f2f4);color:var(--text-secondary,#666);padding:0 7px;font-size:10px}.avatar-editor input{display:none}.error{margin:-5px 0 8px;color:#c24a4a;font-size:10px}.scroll>label{display:block;padding:9px 0;border-top:1px solid var(--border-color,rgba(0,0,0,.05))}.scroll>label>span,.option-block>span{display:block;margin-bottom:6px;color:var(--text-secondary,#666);font-size:11px;font-weight:570}.scroll>label input,.scroll>label textarea{box-sizing:border-box;width:100%;border:1px solid var(--border-color,#e3e4e6);border-radius:9px;background:var(--sys-bg-primary,#f7f7f8);color:var(--text-primary,#222);padding:8px 9px;font:inherit;font-size:12px;outline:0}.scroll>label input{height:34px}.scroll>label textarea{min-height:58px;resize:vertical;line-height:1.5}.option-block{padding:9px 0;border-top:1px solid var(--border-color,rgba(0,0,0,.05))}.choices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px}.choices button,.permission-list button{height:29px;border:1px solid transparent;border-radius:8px;background:var(--sys-bg-primary,#f2f3f5);color:var(--text-secondary,#666);font:inherit;font-size:10.5px}.choices button.active,.permission-list button.active{border-color:color-mix(in srgb,var(--accent-color,#2b7de9) 38%,transparent);background:color-mix(in srgb,var(--accent-color,#2b7de9) 9%,transparent);color:var(--accent-color,#2b7de9)}.permission-list{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:5px}.permission-list button{min-width:0;padding:0 2px;white-space:nowrap}.permission-list i{display:none;font-style:normal}.permission-list button.active i{display:inline;margin-right:2px}@media(max-width:340px){.scroll{padding-left:12px;padding-right:12px}.permission-list{grid-template-columns:repeat(4,minmax(0,1fr))}.avatar-editor p{max-width:190px}}
.overlay{position:fixed}
</style>
